#!/usr/bin/env bash
set -euo pipefail

usage() {
  cat <<EOF
usage: $0 NAME...
Greets each NAME.
EOF
}

(( $# >= 1 )) || { usage >&2; exit 64; }

for name in "$@"; do
  echo "Hello, $name!"
done

#!/usr/bin/env bash
set -euo pipefail

usage() {
  cat <<EOF
usage: $0 [-h] [-v] [-n COUNT] FILE...
Prints the last COUNT lines (default 5) of each FILE.

  -h        show this help and exit
  -v        print a heading before each file
  -n COUNT  print COUNT lines
EOF
}

count=5
verbose=0
while getopts ":hn:v" opt; do
  case $opt in
    h) usage; exit 0 ;;
    n) count=$OPTARG ;;
    v) verbose=1 ;;
    \?) echo "unknown option: -$OPTARG" >&2; usage >&2; exit 64 ;;
    :) echo "option -$OPTARG needs a value" >&2; usage >&2; exit 64 ;;
  esac
done
shift $((OPTIND - 1))
(( $# >= 1 )) || { usage >&2; exit 64; }

for file in "$@"; do
  if (( verbose )); then
    echo "==> $file <=="
  fi
  tail -n "$count" -- "$file"
done

#!/usr/bin/env bash
set -euo pipefail

level=INFO
quiet=0
while (( $# > 0 )); do
  case $1 in
    --level=*) level=${1#*=} ;;
    --level)
      (( $# >= 2 )) || { echo "--level needs a value" >&2; exit 64; }
      level=$2
      shift
      ;;
    --quiet) quiet=1 ;;
    --) shift; break ;;
    -*) echo "unknown option: $1" >&2; exit 64 ;;
    *) break ;;
  esac
  shift
done

echo "level=$level quiet=$quiet"
echo "files: $#"
for file in "$@"; do
  echo "file: $file"
done

#!/usr/bin/env bash
set -euo pipefail

usage() {
  echo "usage: $0 [--open | --done] [--prefix TEXT] [FILE]"
}

main() {
  local want="" prefix="- "
  while (( $# > 0 )); do
    case $1 in
      --open) want="[ ]" ;;
      --done) want="[x]" ;;
      --prefix=*) prefix=${1#*=} ;;
      --prefix)
        (( $# >= 2 )) || { usage >&2; exit 64; }
        prefix=$2
        shift
        ;;
      --help) usage; exit 0 ;;
      --) shift; break ;;
      -?*) echo "unknown option: $1" >&2; usage >&2; exit 64 ;;
      *) break ;;
    esac
    shift
  done

  local input="${1:--}" line
  while IFS= read -r line; do
    [[ -z $want || ${line:2:3} == "$want" ]] || continue
    printf '%s%s\n' "$prefix" "${line:6}"
  done < <(cat -- "$input")
}

main "$@"

