#!/usr/bin/env bash
set -euo pipefail

usage() {
  echo "usage: $0 --level LEVEL [--since HH:MM] [FILE]"
}

level=""
since="00:00"
while (( $# > 0 )); do
  case $1 in
    --level=*) level=${1#*=} ;;
    --since=*) since=${1#*=} ;;
    --level)
      (( $# >= 2 )) || { usage >&2; exit 64; }
      level=$2
      shift
      ;;
    --since)
      (( $# >= 2 )) || { usage >&2; exit 64; }
      since=$2
      shift
      ;;
    --help) usage; exit 0 ;;
    --) shift; break ;;
    -?*) echo "unknown option: $1" >&2; usage >&2; exit 64 ;;
    *) break ;;
  esac
  shift
done
[[ -n $level ]] || { usage >&2; exit 64; }

input="${1:--}"
while IFS= read -r line; do
  read -r stamp lvl _ <<< "$line"
  [[ $lvl == "$level" ]] || continue
  [[ ${stamp:11:5} < "$since" ]] && continue
  echo "$line"
done < <(cat -- "$input")
